def esc(value):
    return html.escape(str(value), quote=True)


def refs_html(refs):
    return ' '.join('<a href="#source-{0}" title="{1}">[{0}]</a>'.format(esc(s), esc(SOURCES[s]['title'])) for s in dict.fromkeys(refs))


def qualifies(grade):
    return bool(set(grade.split('/')) & {'A', 'B', 'P'})


def write_csv(name, records):
    assert records
    with (ROOT / name).open('w', encoding='utf-8-sig', newline='') as handle:
        writer = csv.DictWriter(handle, fieldnames=list(records[0]))
        writer.writeheader()
        writer.writerows(records)


