SCRIPT = r'''
(() => {
  'use strict';
  const data = JSON.parse(document.getElementById('research-data').textContent);
  const form = document.getElementById('filters');
  const nodes = [...document.querySelectorAll('#inventory-body > tr')];
  const q = document.getElementById('query');
  const family = document.getElementById('family-filter');
  const chapter = document.getElementById('chapter-filter');
  const scope = document.getElementById('scope-filter');
  const decision = document.getElementById('decision-filter');
  let visible = data.inventory.map((_, i) => i);
  function apply() {
    const words = q.value.trim().toLocaleLowerCase().split(/\s+/).filter(Boolean);
    visible = [];
    data.inventory.forEach((r, i) => {
      const dd = r['直驱入选'] === '是', screw = r['丝杠入选'] === '是';
      const scopeOK = scope.value === 'all' || (scope.value === 'dd' && dd) ||
        (scope.value === 'screw' && screw) || (scope.value === 'both' && dd && screw);
      const text = data.search[i];
      const show = scopeOK && (!family.value || r['评估家族'] === family.value) &&
        (!chapter.value || r['原章节'] === chapter.value) && (!decision.value || r['替代结论'] === decision.value) &&
        words.every(w => text.includes(w));
      nodes[i].hidden = !show;
      if (show) visible.push(i);
    });
    document.getElementById('result-count').textContent = `显示 ${visible.length} / ${nodes.length} 个原条目`;
    document.getElementById('no-results').hidden = visible.length !== 0;
  }
  form.addEventListener('input', apply);
  form.addEventListener('change', apply);
  document.getElementById('reset-filters').addEventListener('click', () => { form.reset(); apply(); });
  function cell(value) {
    let s = String(value ?? '');
    if (/^[=+\-@]/.test(s)) s = "'" + s;
    return '"' + s.replace(/"/g, '""') + '"';
  }
  function download(rows, file) {
    if (!rows.length) { document.getElementById('result-count').textContent = '当前无匹配条目，请调整筛选后导出。'; return; }
    const keys = Object.keys(rows[0]);
    const csv = '\uFEFF' + [keys.map(cell).join(','), ...rows.map(r => keys.map(k => cell(r[k])).join(','))].join('\r\n');
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' }));
    const a = document.createElement('a'); a.href = url; a.download = file; document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  }
  document.querySelectorAll('[data-export]').forEach(b => b.addEventListener('click', () => {
    const kind = b.dataset.export;
    const rows = kind === 'filtered' ? visible.map(i => data.inventory[i]) : data[kind];
    download(rows, kind === 'filtered' ? 'semiconductor-domestic-filtered.csv' : data.files[kind]);
  }));
  apply();
})();
'''


def main():
    with (ROOT / 'semiconductor-direct-drive-inventory.csv').open(encoding='utf-8-sig', newline='') as handle:
        original = list(csv.DictReader(handle))
    selected = [r for r in original if qualifies(r['直驱证据等级']) or qualifies(r['丝杠证据等级'])]
    assert len(original) == 403 and len(selected) == 245, '原目录已变化，需重新审计筛选范围'
    assert len({r['评估家族'] for r in selected}) == 37
    for p in PRODUCTS.values():
        assert p['maker'] in MAKERS, p
        assert all(s in SOURCES for s in p['sources']), p
    assert all(s in SOURCES for m in MAKERS.values() for s in m['sources'])
    inventory, search, decisions = [], [], Counter()
    used = set()
    row_ids = set()
    for r in selected:
        key = r['原章节'][:2] + ':' + r['原编号']
        assert key not in row_ids
        row_ids.add(key)
        ids, decision, note = OVERRIDES.get(key, DEFAULTS[r['评估家族'].split()[0]])
        ids = list(dict.fromkeys(ids.split()))
        assert all(cid in PRODUCTS for cid in ids), key
        used.update(ids)
        decisions[decision] += 1
        mids = list(dict.fromkeys(PRODUCTS[c]['maker'] for c in ids))
        refs = list(dict.fromkeys(s for c in ids for s in PRODUCTS[c]['sources']))
        record = {'调研日期': DATE, '条目键': key, **{k:v for k,v in r.items() if k != '调研日期'},
                  '直驱入选': '是' if qualifies(r['直驱证据等级']) else '否',
                  '丝杠入选': '是' if qualifies(r['丝杠证据等级']) else '否',
                  '替代结论': decision, '国产候选ID': ' / '.join(ids),
                  '候选设备/系列': '；'.join(PRODUCTS[c]['model'] for c in ids),
                  '生产厂家及待核主体': '；'.join(MAKERS[m]['name'] for m in mids),
                  '制造来源口径': '；'.join(MAKERS[m]['name']+'：'+MAKERS[m]['origin'] for m in mids),
                  '替代边界与待核事项': note, '国产来源编号': ' / '.join(refs),
                  '国产参考URL': ' | '.join(SOURCES[s]['url'] for s in refs)}
        inventory.append(record)
        search.append((' '.join(str(v) for v in record.values()) + ' ' + ' '.join(PRODUCTS[c]['use'] for c in ids)).lower())
    products = []
    for c,p in PRODUCTS.items():
        m = MAKERS[p['maker']]
        mapped = [r['条目键'] for r in inventory if c in r['国产候选ID'].split(' / ')]
        products.append({'候选ID': c, '生产厂家及待核主体': m['name'], '地区/制造布局': m['city'], '制造来源口径':m['origin'],
                         '设备/系列':p['model'], '用途':p['use'], '产品核实状态':p['status'], '替代边界':p['limit'],
                         '国产机直驱证据':p['dd'], '国产机丝杠证据':p['screw'], '对应原条目':' / '.join(mapped) or '相邻产品/专利线索，未指定量产替代',
                         '参考编号':' / '.join(p['sources']), '参考URL':' | '.join(SOURCES[s]['url'] for s in p['sources']), '调研日期':DATE})
    makers = []
    for mid,m in MAKERS.items():
        cids = [c for c,p in PRODUCTS.items() if p['maker']==mid]
        makers.append({'主体ID':mid, '生产厂家及待核主体':m['name'], '地区/制造布局':m['city'], '制造来源口径':m['origin'],
                       '产品ID':' / '.join(cids), '设备/系列':'；'.join(PRODUCTS[c]['model'] for c in cids),
                       '说明':m['note'], '参考编号':' / '.join(m['sources']), '参考URL':' | '.join(SOURCES[s]['url'] for s in m['sources']), '调研日期':DATE})
    source_records = [{'资料编号':s['id'], '资料标题':s['title'], '资料性质':s['kind'], 'URL':s['url'], '使用边界':s['note'], '核对截至':DATE} for s in SOURCES.values()]
    files = {'inventory':'semiconductor-domestic-alternatives.csv', 'products':'semiconductor-domestic-products.csv',
             'makers':'semiconductor-domestic-manufacturers.csv', 'sources':'semiconductor-domestic-sources.csv'}
    datasets = dict(inventory=inventory, products=products, makers=makers, sources=source_records)
    for kind, name in files.items():
        write_csv(name, datasets[kind])
    dd = sum(r['直驱入选']=='是' for r in inventory)
    screw = sum(r['丝杠入选']=='是' for r in inventory)
    both = sum(r['直驱入选']==r['丝杠入选']=='是' for r in inventory)
    domestic = sum(m['origin'].startswith('境内制造主体') for m in MAKERS.values())
    h = []
    add = h.append
    add('<!DOCTYPE html>\n<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">')
