    add('<meta name="description" content="直驱与丝杠A/B/P设备的中国境内制造替代设备和生产厂家调研，245个原条目逐项对应、产品与厂商索引、参考证据及CSV导出。"><title>国产平替设备与生产厂家｜直驱及丝杠A/B/P专项</title><style>'+CSS+'</style></head><body>')
